    # The review server serves the artifact's directory. Package references
    # inside it instead of relying on parent paths that only work as file://.
    def package_link(match):
        attr,value=match.group(1),html.unescape(match.group(2))
        source=(ROOT/'.lavish'/value).resolve()
        assert source.is_relative_to(ROOT) and source.is_file(),source
        if attr=='src' and source.suffix=='.png':
            return 'src="data:image/png;base64,'+base64.b64encode(source.read_bytes()).decode()+'"'
        relative=Path('remaining-assets')/source.relative_to(ROOT)
        dest=ROOT/'.lavish'/relative;dest.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(source,dest)
        return attr+'="'+html.escape(relative.as_posix(),quote=True)+'"'
    page=re.sub(r'(href|src)="(\.\./[^"]+)"',package_link,page)
    out=ROOT/'.lavish/remaining-grokbot.html';out.write_text(page)
